// All wearable layers share this articulated body in both the world and closet.
export function avatar(o,{pose='idle',phase=0,face=1,back=false,id='person'}={}){
 const skin={cream:['#ffe2c2','#e6b58f'],honey:['#e7b78a','#bb845f'],cocoa:['#af795a','#815139']}[o.skin]||['#ffe2c2','#e6b58f'];const hair={chestnut:'#79523d',black:'#403b39',caramel:'#b9824d',rose:'#a86d64'}[o.hairColor]||'#79523d';
 const top={sailor:['#fff7e9','#ded9c5'],cardigan:['#dba9aa','#b9848d'],tee:['#b6cbb0','#8cab85'],hoodie:['#b7b1ce','#928daa'],blouse:['#f6deb1','#d6bc91'],overall:['#9eafb8','#7e939d']}[o.top];const shoe={cream:'#e4d8ba',brown:'#987455',pink:'#d6a19b',sage:'#90a486'}[o.shoes];const swing=pose==='walk'?Math.sin(phase)*17:0,sitting=pose==='sit',work=pose==='water'||pose==='plant';const leg=(x,v)=>`<g transform="rotate(${sitting?-67:v} ${x} -23)"><path d="M${x-6}-28q6-4 12 0l-1 23h-10z" fill="${o.bottom==='trousers'?'#a99e89':skin[0]}"/><path d="M${x-6}-9h11v8q-6 5-14 0v-5z" fill="${shoe}"/><path d="M${x-5}-3h10" stroke="#fff6e2" stroke-width="2"/></g>`;
 const sleeves=o.top==='tee'?16:24;
 const arm=(x,rot)=>`<g transform="rotate(${rot} ${x} -53)"><path d="M${x-5}-56q5-4 10 0l1 ${sleeves}q-6 5-12 0z" fill="url(#${id}-cloth)"/><path d="M${x-4} ${-54+sleeves}v11q4 8 9 0v-11" fill="${skin[0]}"/></g>`;
 return `<defs><linearGradient id="${id}-skin" x1="0" y1="0" x2="1" y2=".6"><stop stop-color="${skin[0]}"/><stop offset="1" stop-color="${skin[1]}"/></linearGradient><linearGradient id="${id}-cloth" x2=".9" y2="1"><stop stop-color="${top[0]}"/><stop offset="1" stop-color="${top[1]}"/></linearGradient><radialGradient id="${id}-hair"><stop stop-color="${hair}"/><stop offset="1" stop-color="${hair}" stop-opacity=".92"/></radialGradient></defs><ellipse cy="6" rx="23" ry="8" fill="#596b4b20"/><g transform="scale(${face} 1) translate(0 ${pose==='walk'?Math.abs(Math.sin(phase))*-2:0})">${o.hair==='twin'?`<path d="M-21-85q-25-6-18 25t17 4M21-85q25-6 18 25t-17 4" fill="${hair}"/>`:o.hair==='wave'?`<path d="M-24-86q-14 24-8 40t11 4M24-86q14 24 8 40t-11 4" fill="${hair}"/>`:''}${leg(-9,swing)}${leg(9,-swing)}
 <path d="M-19-36q18-8 38 0l-3 13H2l-2-7-2 7h-16z" fill="${o.bottom==='trousers'?'#a99e89':'#a4afa1'}"/>
 ${arm(-20,work?-53:-swing*.7)}<path d="M-15-61q15-7 30 0l8 28q-21 13-46 0z" fill="url(#${id}-cloth)" stroke="${top[1]}" stroke-width=".7"/>${o.bottom==='skirt'||o.bottom==='pleats'?`<path d="M-18-34h36l8 16q-25 10-52 0z" fill="${o.bottom==='skirt'?'#d4a8a0':'#aeb8a1'}"/>${o.bottom==='pleats'?'<path d="M-12-30l-3 13M0-30v15M12-30l3 13" stroke="#87947d" stroke-width="1.5"/>':''}`:''}
 ${o.top==='sailor'?'<path d="M-13-61L0-47l13-14-3 18H-10z" fill="#768d97"/><path d="M-12-60L0-49l12-11" fill="none" stroke="#fff9ee" stroke-width="2"/><path d="M-3-48h6l3 12-6-3-5 3z" fill="#b37e72"/>':o.top==='cardigan'?'<path d="M0-61v27M-13-45h8M8-45h8" stroke="#f9e8d5" stroke-width="2"/><circle cy="-44" r="1.5" fill="#b77d73"/>':o.top==='hoodie'?'<path d="M-13-61q13 15 26 0M-7-57v13M7-57v13M-9-39h18" fill="none" stroke="#e9e4f0" stroke-width="2"/>':o.top==='blouse'?'<path d="M-13-61q5 14 13 2 8 12 13-2" fill="#fff7df"/><path d="M0-54q-15-12-13 0t13 0q15-12 13 0T0-54" fill="#bc8d8a"/>':o.top==='overall'?'<path d="M-11-60v16M11-60v16" stroke="#eee7d0" stroke-width="5"/><path d="M-15-47h30v14H-15z" fill="#80969d"/><path d="M-6-45h12v8H-6z" fill="#a9bdc2"/>':'<path d="M-7-48q8-9 13 0l-6 8z" fill="#f1e7c4"/>'}
 ${arm(20,work?-70:swing*.7)}<path d="M-7-65h14v9q-7 6-14 0" fill="${skin[1]}"/>
 <ellipse cy="-87" rx="27" ry="29" fill="${hair}"/>
 ${back?`<ellipse cy="-85" rx="27" ry="28" fill="url(#${id}-hair)"/><path d="M-13-107q-9 18-5 35M0-110q-6 15-3 28" fill="none" stroke="#ffffff18" stroke-width="3"/>`:`<ellipse cx="-24" cy="-80" rx="5" ry="7" fill="${skin[1]}"/><ellipse cx="24" cy="-80" rx="5" ry="7" fill="${skin[1]}"/><ellipse cy="-82" rx="24" ry="25" fill="url(#${id}-skin)"/><path d="${o.hair==='short'?'M-27-88q-1-32 28-28 27 1 26 29l-12-14-9 7-11-8-11 12-9-1z':o.hair==='wave'?'M-27-88q-3-31 27-28 32 0 27 32l-8-5-1-15q-13 22-36 12l-1 19-10 2z':'M-27-85q-4-31 27-31 33 0 27 35l-8-1-3-17-11 5-2-11-7 12-11-2-3 19-9 1z'}" fill="url(#${id}-hair)"/><path d="M-18-104q12-12 28-6" stroke="#ffffff23" stroke-width="4" fill="none" stroke-linecap="round"/><ellipse cx="-9" cy="-80" rx="3.8" ry="5" fill="#4b3e35"/><ellipse cx="10" cy="-80" rx="3.8" ry="5" fill="#4b3e35"/><circle cx="-10" cy="-82" r="1.4" fill="#fffbed"/><circle cx="9" cy="-82" r="1.4" fill="#fffbed"/><ellipse cx="-16" cy="-72" rx="5" ry="2.5" fill="#de9e8e" opacity=".45"/><ellipse cx="17" cy="-72" rx="5" ry="2.5" fill="#de9e8e" opacity=".45"/><path d="M-3-68q4 4 8-1" stroke="#b57e69" stroke-width="1.5" fill="none" stroke-linecap="round"/>`}
 ${o.hat==='straw'?'<ellipse cy="-105" rx="36" ry="9" fill="#d9bd7f"/><path d="M-23-107l4-17q20-14 39 0l3 17" fill="#e5cb91"/><path d="M-23-107q23 7 46 0" stroke="#b78c72" stroke-width="5" fill="none"/>':o.hat==='beret'?'<path d="M-28-106q-7-28 24-24 35-10 34 18l-10 10z" fill="#c79393"/><path d="M-1-130v-6" stroke="#9d7770" stroke-width="4"/>':o.hat==='bow'?'<path d="M-26-104q26-18 52 0" stroke="#d8a3a3" stroke-width="4" fill="none"/><path d="M15-111q-19-26-22-7t22 7q28-14 19-22t-19 22" fill="#e4b0aa"/>':''}
 ${o.accessory==='bag'?'<path d="M-18-58l35 27" stroke="#b69a73" stroke-width="4"/><rect x="9" y="-37" width="19" height="16" rx="5" fill="#d4b88a" stroke="#af926b"/><path d="M13-33h11" stroke="#f1d8aa" stroke-width="2"/>':o.accessory==='scarf'?'<path d="M-12-59q12 7 24 0l2 7q-14 7-28 0zM5-53l13 18 7-7-13-13" fill="#b98178"/><path d="M-12-54h24M12-47l7 8" stroke="#e4c5a6" stroke-width="2"/>':o.accessory==='glasses'&&!back?'<g fill="none" stroke="#97886f" stroke-width="1.6"><circle cx="-9" cy="-80" r="8"/><circle cx="10" cy="-80" r="8"/><path d="M-1-80h3M-18-82l-6-2M18-82l6-2"/></g>':''}
 ${work?'<g transform="translate(29 -37) rotate(-20)"><path d="M-7-12h19v20H-7z" fill="#a5c0b6"/><path d="M11-8l19-7 3 6-21 12M-7-10q-17-4-15 8t15 7" stroke="#7ea399" stroke-width="4" fill="none"/><ellipse cx="32" cy="-12" rx="6" ry="4" fill="#b8d2c6"/></g>':''}</g>`;
}
